"""Build the Week 9 demonstration notebook using the existing project kernel."""
from pathlib import Path
import nbformat as nbf

ROOT=Path(__file__).resolve().parents[1]


def main():
    md,code=nbf.v4.new_markdown_cell,nbf.v4.new_code_cell
    nb=nbf.v4.new_notebook(cells=[
        md('# Week 9: Fair Housing Compliance Screening\n\nScreen proposed listing language for possible preferences, limitations and exclusions. This is a rule-based educational screen, not a legal certification. It does not infer applicant characteristics or publish listings. The project implements error / warning / info levels, a synthetic evaluation, a real-sample scan and a submission-workflow example.'),
        code('from pathlib import Path\nimport sys, json\nROOT = next(p for p in [Path.cwd(), *Path.cwd().parents] if (p / "scripts/compliance_checker.py").is_file())\nif str(ROOT) not in sys.path:\n    sys.path.insert(0, str(ROOT))\nimport pandas as pd\nfrom IPython.display import display\nfrom scripts.compliance_checker import ComplianceChecker\nfrom scripts.listing_submission import prepare_listing_submission\nfrom scripts.evaluate_week9 import run_evaluation\nchecker = ComplianceChecker()\nprint("Python:", sys.executable)\nprint("Rule library:", checker.version, "| Rules:", len(checker.rules))'),
        md('## 1. Rule library and protected categories\n\nRules cover race, color, national origin, religion, sex, familial status and disability. The library stores patterns, explanations, suggested editing directions and source URLs. This is not a universal banned-word list. An exclusion such as “no children” is different from white cabinets or a nearby religious facility.\n\nLegal sources: [42 U.S.C. 3604(c)](https://uscode.house.gov/us/usc/t42/s3604/), [24 CFR 100.75](https://www.ecfr.gov/current/title-24/subtitle-B/chapter-I/part-100/subpart-B/section-100.75), and the limited provisions in [42 U.S.C. 3607](https://uscode.house.gov/us/usc/t42/s3607/).'),
        code('rules = pd.DataFrame(checker.rules)\ndisplay(rules.groupby(["category", "severity"]).size().unstack(fill_value=0))\ndisplay(rules[["id", "category", "severity", "message"]])'),
        md('## 2. Three severity levels and evidence\n\n- error: block this submission for correction.\n- warning: require qualified human review; no automatic publication.\n- info: explanatory context, not a positive violation detection.\n\nResults include matched text, local context, normalized-text offsets, suggested editing directions and source links. The compatibility key compliant means only that the current screening policy passed. legal_compliance_certified is always false.'),
        code('examples = [\n    "A bright home. No children.",\n    "Applicants must be able-bodied.",\n    "White tenants only.",\n    "Christians only.",\n    "Perfect for singles.",\n    "55+ community; adults only.",\n    "Female roommate wanted.",\n    "Wheelchair accessible entrance.",\n    "White cabinets and black granite countertops.",\n    "A diverse area with ethnic restaurants nearby.",\n]\ndisplay(pd.DataFrame([{"text": t, "decision": (r := checker.check_listing(t))["decision"], **r["counts"]} for t in examples]))\ndisplay(pd.DataFrame(checker.check_listing(examples[0])["findings"]))'),
        md('## 3. Context and false-positive controls\n\nNormalization handles case, whitespace, HTML entities/tags, dash variants and Unicode width variants. Explicitly rejected phrases and clear historical wording with an inclusive replacement retain informational matches. An owner quoting a current exclusion still produces a risk finding. An inclusive slogan cannot erase an exclusion elsewhere.\n\nSenior housing, claimed religious-organization housing and shared-living phrases are routed to review; a keyword never proves a legal exception. No automated human override is implemented.'),
        code('context_examples = [\n    \'Do not use the phrase "no children".\',\n    \'Previously "white tenants only", now everyone is welcome.\',\n    "All are welcome. No children.",\n    "The owner says \'no children\'.",\n    "No wheelchair ramp is installed.",\n    "Christian tenants only. Owned by a religious organization.",\n]\ndisplay(pd.DataFrame([{"text": t, "decision": (r := checker.check_listing(t))["decision"], "context_reasons": [f["context_reason"] for f in r["findings"]], **r["counts"]} for t in context_examples]))'),
        md('## 4. Evaluation protocol and actual results\n\nThe development set has 68 examples and the test set 103. Labels are assistant-authored synthetic judgments, not independently human-verified legal labels. The texts are disjoint but phrase families overlap; the fixtures were used during development. They are regression tests, not a blind deployment benchmark.\n\nCase-level screening counts error or warning as positive; info alone is negative. Both known_violation and review labels require a flag. The known-violation recall target is reported separately, along with error-only recall, per-category recall, precision, F1 and decision accuracy. All mismatches are retained. A perfect synthetic score would not establish real-world perfection.'),
        code('report = run_evaluation()\nmetric_rows = []\nfor split, r in report["splits"].items():\n    metric_rows.append({"split": split, "cases": r["count"], **r["confusion"], "precision": r["screening_precision"], "screening_recall": r["screening_recall"], "known_violation_recall": r["known_violation_recall"], "known_violation_error_recall": r["known_violation_error_recall"], "decision_accuracy": r["decision_accuracy"]})\ndisplay(pd.DataFrame(metric_rows))\nprint("Test targets:", report["splits"]["test"]["targets_met"])\nprint("Status:", report["evaluation_status"])\ndisplay(pd.DataFrame(report["splits"]["test"]["per_category_known_violation_recall"]).T)'),
        md('## 5. Screening real listing remarks and Week 8 summaries\n\nThe evaluator also screens the Week 1 sample and any saved Week 8 summaries. These records are unlabeled for this task: flag counts are not proven violation counts, and no precision/recall is calculated for them. Older-person housing and other review flags may be legitimate descriptions requiring verification.\n\nThe complete findings are saved locally in data/processed/week9_sample_screening.jsonl. They do not modify listing descriptions, change Week 8 scores, or publish anything.'),
        code('print(json.dumps(report.get("real_sample_scan", {"status": "no local sample available"}), indent=2))\nscan_path = ROOT / "data/processed/week9_sample_screening.jsonl"\nif scan_path.exists():\n    scan = [json.loads(line) for line in scan_path.read_text().splitlines()]\n    flags = [{"listing_id": r["listing_id"], "field": field, "decision": result["decision"], "finding": f["matched_text"], "severity": f["severity"], "reason": f["message"]} for r in scan for field, result in r["checks"].items() for f in result["findings"] if f["severity"] != "info"]\n    display(pd.DataFrame(flags).head(12))'),
        md('## 6. Listing submission workflow with Week 8\n\nprepare_listing_submission checks original remarks before generating a summary. If the original description is blocked or requires review, a neutral summary cannot make it pass. A supplied or generated summary is also checked. The result is blocked, pending_review or ready_for_submission. published remains false: this is a local simulation, not a publishing service.'),
        code('submission_examples = [\n    {"L_ListingID": "demo-block", "remarks": "A bright home. No children.", "summary": "A bright home."},\n    {"L_ListingID": "demo-review", "remarks": "55+ community; adults only."},\n    {"L_ListingID": "demo-ready", "L_City": "Irvine", "beds": 3, "baths": 2, "price": 950000, "remarks": "This Irvine home has 3 bedrooms and 2 bathrooms. A private pool is included."},\n]\nsubmissions = [prepare_listing_submission(r, checker=checker) for r in submission_examples]\ndisplay(pd.DataFrame([{k: r[k] for k in ("listing_id", "status", "can_submit", "published", "summary", "message")} for r in submissions]))'),
        md('## 7. Try another description\n\nThis optional widget runs the same local checker. It does not save a submission or send text to an external service. Use the project kernel and run this cell to activate the button.'),
        code('import ipywidgets as widgets\ntext_input = widgets.Textarea(value="A bright 3-bedroom home. No children.", description="Description:", rows=4, layout=widgets.Layout(width="100%"), style={"description_width": "95px"})\ncheck_button = widgets.Button(description="Check language", button_style="primary")\ncheck_output = widgets.Output()\ndef check_description(_=None):\n    with check_output:\n        check_output.clear_output(wait=True)\n        result = checker.check_listing(text_input.value)\n        print("Decision:", result["decision"], "|", result["counts"])\n        print("Legal compliance certified:", result["legal_compliance_certified"])\n        if result["findings"]:\n            display(pd.DataFrame(result["findings"])[["category", "severity", "matched_text", "message", "suggestion"]])\ncheck_button.on_click(check_description)\ndisplay(widgets.VBox([text_input, check_button, check_output]))\ncheck_description()'),
        md('## 8. Tests, limitations and remaining review\n\nRun python -m pytest -q tests/test_week9.py. Tests cover all fixture labels and severity expectations, category coverage, Unicode/HTML, quotations, false-positive/negative metric accounting, invalid inputs and submission routing. The integration confirms that Week 8 summaries are checked and no real publication occurs.\n\nInitial error analysis found a false positive on formerly discriminatory wording followed by now everyone is welcome. The local grammar/context guard was corrected without changing the fixture label. Development used these regression examples, so the final scores are not an independent blind test.\n\nBefore claiming deployment readiness, obtain independent human/legal review of labels and rules, evaluate naturally occurring listings and paraphrases, document local/state scope, and define an audited human review process. The checker does not infer resident identities or decide applicant eligibility. See docs/week9_fair_housing.md for team guidance and sources.'),
    ],metadata={'kernelspec':{'name':'idx-exchange-nlp','display_name':'IDX Exchange NLP (.venv)','language':'python'},
                'language_info':{'name':'python'}})
    path=ROOT/'notebooks/week9_fair_housing_compliance.ipynb'
    if path.exists():
        raise FileExistsError(f'Preserve the existing notebook and outputs: {path}')
    nbf.write(nb,path)
    print(path)


if __name__=='__main__':
    main()
